def holon_keys(index):
    _s0_inverted = {}
    for _s0_key, _s0_value in index.items():
        _s0_inverted.setdefault(_s0_value, []).append(_s0_key)
    step_1 = _s0_inverted
    step_2 = sorted(step_1.keys())
    _s2_floor = 0.0
    _s2_peak = max(step_2) if step_2 else _s2_floor
    return _s2_peak if _s2_peak > _s2_floor else _s2_floor
